import{_ as a,o as i,c as t,a0 as s}from"./chunks/framework.DPd3ST4h.js";const u=JSON.parse('{"title":"Code-index action","description":"","frontmatter":{},"headers":[],"relativePath":"code-index-action.md","filePath":"code-index-action.md","lastUpdated":1793124037000}'),n={name:"code-index-action.md"};function o(r,e,d,l,c,h){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="code-index-action" tabindex="-1">Code-index action <a class="header-anchor" href="#code-index-action" aria-label="Permalink to &quot;Code-index action&quot;">​</a></h1><p><code>github/code-index</code> is a secondary composite action that prepares bounded code context or an exact-revision provider cache. The published Redline action invokes it before review execution. The review core does not install an indexer, open an index database, or invoke provider commands.</p><p>The action supports two pinned providers:</p><ul><li><strong>CodeGraphContext (CGC) 0.5.7</strong> with embedded FalkorDB on Linux x64. Its standalone MIT-licensed binary is pinned by version and SHA-256 digest.</li><li><strong>GitNexus 1.6.12</strong> with LadybugDB on Linux x64 and arm64. Its npm archive and dependency lock are digest-pinned, lifecycle scripts and embeddings are disabled, and required native packages are validated before use. GitNexus is distributed under the PolyForm Noncommercial License 1.0.0; users selecting it are responsible for confirming that their use satisfies that license.</li></ul><p>Unsupported platforms produce an <code>unsupported</code> artifact instead of blocking file-only review.</p><h2 id="root-action-integration" tabindex="-1">Root action integration <a class="header-anchor" href="#root-action-integration" aria-label="Permalink to &quot;Root action integration&quot;">​</a></h2><p>Consumers invoke only the published Redline action. A configured review enables indexing by default with CGC; <code>indexing: disabled</code> is the explicit file-only mode. Select GitNexus with <code>indexing-provider: gitnexus</code>.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Run Redline review</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  uses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">dragoscirjan/redline/github@v1.0.0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pi</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    model-config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${{ vars.REDLINE_MODEL_CONFIG }}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    model-auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${{ secrets.MODEL_CREDENTIALS }}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    indexing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">enabled</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # default; set disabled for file-only review</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    indexing-provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">cgc</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # default; or gitnexus</span></span></code></pre></div><p>Inside <code>github/action.yaml</code>, the root composite invokes <code>uses: $/github/code-index</code> after fetching the exact base and head commits. GitHub.com&#39;s <code>$/</code> self-repository reference resolves the child action at the root action&#39;s exact running commit, so a consumer pinned to a version tag or commit cannot receive a different index action. It also avoids <code>./</code>, which would resolve against the consumer&#39;s workspace. GitHub Enterprise Server does not support <code>$/</code>; it is outside this action&#39;s current platform scope.</p><p>The child writes <code>code-context.json</code> and exposes its absolute path and coverage status to the root action. The root passes that generated path through the internal review environment contract and includes the artifact in the downloadable context bundle. Consuming workflows select <code>cgc</code> or <code>gitnexus</code> through <code>indexing-provider</code>; they do not supply a context path or provider-internal commands, storage paths, or execution settings.</p><p>The review validates the artifact identity and resolves every selected span again from its captured exact-head source. Missing, invalid, unsupported, or unavailable context remains file-only review with explicit degraded coverage.</p><h2 id="default-branch-warmup" tabindex="-1">Default-branch warmup <a class="header-anchor" href="#default-branch-warmup" aria-label="Permalink to &quot;Default-branch warmup&quot;">​</a></h2><p><code>.github/workflows/code-index-warmup.yml</code> runs after every push to <code>main</code>. It checks out that exact trusted revision, then warms CGC and GitNexus with a two-job maximum. Workflow concurrency cancels an older warmup when a newer default-branch revision arrives, so only the newest base continues.</p><p>The warmup calls the same secondary action in <code>warmup</code> mode with identical base and head revisions. It therefore uses the same provider pin, platform identity, configuration digest, repository digest, database validation, and cache key format as pull-request review. A later pull request based on that revision restores the validated database and records <code>indexMs: 0</code>.</p><p>Each provider job writes a step summary and uploads <code>code-context.json</code>. The summary records the validated hit or save result, cache identity, cache size, index time, and total measured time. Review artifacts record the validated hit diagnostic and index timing, so warmup-to-review hit rates can be calculated from workflow artifacts. Warmup failures fail only the post-push warmup job; they cannot block the merge that already produced the revision. Reviews still degrade to normal cold indexing or file-only coverage when the cache is absent.</p><p>The workflow executes only trusted Redline tooling from the default branch. Provider input is an action-created <code>git archive</code>; it does not execute indexed source, repository hooks, provider configuration, tests, or package scripts from pull requests.</p><h2 id="what-the-action-does" tabindex="-1">What the action does <a class="header-anchor" href="#what-the-action-does" aria-label="Permalink to &quot;What the action does&quot;">​</a></h2><ol><li>Acquires and validates the selected pinned provider without using pull-request package files.</li><li>Restores that provider&#39;s exact pull request base-revision database with <code>actions/cache/restore</code>.</li><li>Exports both the exact base and exact head with <code>git archive</code>.</li><li>Removes symlinks and repository-supplied provider configuration from both temporary source trees.</li><li>Validates and reuses a restored base database without running provider indexing again.</li><li>On a cache miss or invalid restore, indexes the full exported base repository when at least one changed file can use graph context.</li><li>In <code>warmup</code> mode, indexes the exact default-branch revision even though base and head are identical.</li><li>In review mode, returns explicit unsupported or partial context without cold indexing when no changed file can anchor a query.</li><li>Uses supported changed files that exist in the base graph as bounded relationship-query anchors.</li><li>Resolves every selected path and line range against the exported exact-head source.</li><li>Writes the provider-neutral bounded artifact atomically.</li><li>Saves a validated base database only after a cache miss or invalid restore.</li></ol><p>The indexed repository&#39;s builds, scripts, package installers, tests, and Git hooks are never run. The warmup workflow builds only trusted Redline tooling from the default branch when the GitNexus installer is required. GitNexus runs in <code>--index-only --skip-git --skip-fts</code> mode against an action-created archive and action-owned storage; repository AI-context files and skills are never generated. The graph is identified by <code>pull_request.base.sha</code>, so every new head commit in the same pull request reuses it without re-indexing. If the base revision changes, the action creates a new cache. New head-only files receive explicit partial graph coverage, while every selected span is still re-resolved from captured exact-head source.</p><h2 id="artifact-contract" tabindex="-1">Artifact contract <a class="header-anchor" href="#artifact-contract" aria-label="Permalink to &quot;Artifact contract&quot;">​</a></h2><p>The version 2 artifact contains:</p><ul><li>provider ID and exact version;</li><li>repository, exact head revision, and the exact base graph revision when a validated database exists;</li><li>top-level coverage status;</li><li>per-changed-file coverage;</li><li>related repository path, one-based line range, and fixed selection reason;</li><li>for each source-resolved provider result, a bounded action-produced graph reference whose digest binds the provider, version, base snapshot, capability, query identity, relationship, and resolution to that exact span;</li><li>bounded diagnostics;</li><li>separate installation, restore, database-validation, relationship-query, index, and save timings. Legacy version-1 artifacts remain readable; aggregate reporting treats their missing validation timing as zero.</li></ul><p>It contains no graph database, source text, credentials, model conclusions, or finding locations. The strict parser is exported from <code>src/code-context/artifact.ts</code>. Limits include 256 changed files, 64 related spans, eight spans per changed file, 80 lines per span, 48 KiB of resolved source coverage, 20 diagnostics, and a 128 KiB artifact.</p><p><code>complete</code> means every represented, supported changed file exists in the base graph and was queried within the limits. <code>partial</code> records a supported head-only file that is absent from the base graph, any unsupported file mixed with supported coverage, failed query direction, invalid provider row, or truncation. <code>unsupported</code> means no changed head file can anchor a provider query. <code>unavailable</code> means indexing or validation failed. Empty successful query output is only empty context; it is not proof that no relationship exists.</p><h2 id="provider-value-benchmark" tabindex="-1">Provider value benchmark <a class="header-anchor" href="#provider-value-benchmark" aria-label="Permalink to &quot;Provider value benchmark&quot;">​</a></h2><p><code>mise run benchmark:code-index-value</code> regenerates <code>benchmark/code-index-value/v1/report.json</code> and <code>report.md</code> from the checked-in capture. The report compares three cold and three validated exact-base warm runs for both providers on the two-file TypeScript fixture and the Redline repository. It also includes three GitHub-hosted default-branch warmup runs per provider, bounded follow-up samples, prompt and source-byte cost, review-quality evidence, failures, cache size, and licensing.</p><p>The current capture separates three conclusions:</p><ul><li><strong>Capability:</strong> GitNexus returned complete source-confirmed context in every current local sample. CGC returned partial context with zero related spans because its bounded incoming query failed.</li><li><strong>Latency:</strong> exact-base restoration removed indexing for both providers. GitNexus had materially lower validation, query, and wall time in these samples.</li><li><strong>Review value:</strong> the historical live-model comparison gained no credited issues and removed no false positives, while adding 1,039 prompt bytes and 216 source bytes. The deterministic recorded comparison shows possible value but is not live-provider evidence.</li></ul><p>The default remains CGC. GitNexus is not an unconditional default because its PolyForm Noncommercial 1.0.0 license requires use-specific review. The measurements do not enable independent verification or follow-up publication. Normal <code>summary.json</code> and <code>summary.md</code> now retain cache disposition, diagnostic codes, and install/restore/validation/index/query/save timings with the existing context span and source-byte counts.</p><h2 id="action-owned-follow-up-gated-off" tabindex="-1">Action-owned follow-up (gated off) <a class="header-anchor" href="#action-owned-follow-up-gated-off" aria-label="Permalink to &quot;Action-owned follow-up (gated off)&quot;">​</a></h2><p>The trusted root action contains a separate <code>github/code-index/follow-up.py</code> worker and a bounded TypeScript adapter. Discovery version 4 may request up to four candidate-indexed <code>incoming</code>/<code>outgoing</code> relationships per file. Review code first validates the candidate and derives the changed path; it never accepts a model query, symbol, command, provider, or arbitrary file path. The adapter sends only a fixed depth-one, fan-out-eight, result-eight request to the trusted worker. Each request is bounded to 20 seconds, with a 120-second worker deadline and cumulative review-run budgets.</p><p>The worker checks the reviewed manifest file, repository, head, provider pin, configuration, exact base cache state, and safe base/head source trees. It generates a fixed provider query, refuses truncated or invalid rows, and attaches an exact-head start-line anchor only when the source is captured and readable. The review core re-resolves that anchor from its separate review bundle; graph labels and empty query results do not establish publication claims. A missing, stale, unsupported, or failed query is an explicit unavailable/incomplete result and may not silently fall back to a guessed source. The review core records <code>source-disagreement</code> when a returned span conflicts with captured source, and <code>source-unavailable</code> when it cannot read that source. An empty or missing worker result has a different diagnostic from an oversized result.</p><p>Offline tests exercise both fake providers, stale snapshots, malformed model-controlled requests, provider failures, missing source, and source-backed verifier integration. Pinned-provider smoke benchmarks also execute five sequential follow-up queries against a small TypeScript fixture. Both providers return one expected, source-confirmed incoming span with complete capability coverage. The observed median/p95-nearest-rank latency was 5,976/6,083 ms for CGC 0.5.7 and 144/153 ms for GitNexus 1.6.12. The no-index fallback makes zero provider calls, returns zero spans, and records required incomplete coverage. These small synthetic samples prove the bounded provider path, not production latency or verifier quality. The checked-in report is at <code>benchmark/review-quality/follow-up-v1/live-providers/report.md</code>.</p><p>This worker is <strong>not</strong> activated in the published action. <code>CODE_INDEX_VERIFICATION_ENABLED</code> is hardcoded to <code>false</code> pending separately judged live recall, clean-change and latency gates. It never runs when the verifier is disabled.</p><h2 id="cache-keys" tabindex="-1">Cache keys <a class="header-anchor" href="#cache-keys" aria-label="Permalink to &quot;Cache keys&quot;">​</a></h2><p>The provider-specific key prefixes are:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>redline-code-index-v2-cgc-0.5.7-linux-x64-&lt;repository-digest&gt;-&lt;configuration-digest&gt;</span></span>
<span class="line"><span>redline-code-index-v2-gitnexus-1.6.12-&lt;platform&gt;-&lt;repository-digest&gt;-&lt;configuration-digest&gt;</span></span></code></pre></div><p>The save key adds the exact base SHA, workflow run ID, and attempt. The only restore prefix includes that same exact base SHA; there is no cross-base or cross-provider fallback. A valid restored database is queried directly, no indexing command runs, and the existing cache is not saved again. The run suffix allows a validated rebuild to supersede an immutable invalid cache entry.</p><p>The cache root contains only provider database files, the provider&#39;s bounded registry when required, and a small identity sidecar. The action rejects symlinks and non-regular entries and verifies provider version, repository, configuration, exact base revision, stable source path, and a bounded graph query before reuse. Default-branch warmup prepares caches when a review has no useful query anchor; unsupported-only reviews no longer pay that cold-index cost. Cache restore or save failure does not invalidate context produced during the current run.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>Normal CI uses fake CGC and GitNexus providers and performs no provider download. It covers cold and restored-base equivalence, exact-base warmup followed by a zero-index review hit, unsupported-only and all-head-new cold-index avoidance, no-reindex reuse across head commits, exact-base and provider cache identity, invalid restore rebuilding, bounded queries, source validation, and provider failure fallback.</p><p>Live smoke tests are separate opt-ins:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_LIVE_CODE_INDEX_TESTS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_LIVE_GITNEXUS_TESTS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>The first downloads pinned CGC. The second runs the trusted pinned GitNexus installer and may take substantially longer because its locked npm dependency tree is acquired for the test. <code>mise run benchmark:live-follow-up</code> runs both fixtures and reports five sequential action-owned follow-up samples per provider.</p>`,44)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
